C=[]
C.append(human('li_daqiu','厉大遒',
'厉大遒住进医院时，是一名脾气古怪、患肺癌的老人，三个女儿陪他入院，却对父亲真正经历过什么知道得很少。他对医生讨论的生殖问题偶然插话，显出的知识远超过一个普通病人的兴趣。遗嘱与保险箱把他的过去留给原振侠：他曾在医学研究中走得极远，试图用新激素跨越不同动物之间的生殖界限，并以自己的材料培育出令他震惊的胚胎。当他意识到这个不可测的生命也是自己的儿子时，科学突破不再只是可以发表的结果，而变成无法轻易承受的亲子与伦理问题。他中止胚胎发育，放下事业，后来的生活仍被那个决定反复追赶。临终时，他想让秘密被理解，又难以完整说出，保险箱和文字成为迂回的交代。陈阿牛继承资料后继续实验，将他尚未走完的路推进更远，也酿成新的毁灭。卡片不能把厉大遒写成随手制造怪物的战斗召唤者：他需要实验条件与长期工作，最关键的限制恰是他对自己所造生命的责任感与恐惧。若恢复行动，他可以在新问题面前展现出惊人设想，但每一个设想都应追问产生的生命是否会被当作可随时丢弃的结果。',
'患癌去世，遗留保险箱与实验记录；记录后来随陈阿牛实验室毁灭。','生殖医学研究与虚构激素实验；能跨越通常生殖界限，但须实验室与资料。','理解和创造生命，又无法轻易面对创造后的责任。',
[('突破在望','技术成功却会产生有感受的新生命','暂停只按成功率衡量，讨论后续照护与主体地位。'),('秘密追问','他人只想得到公式而不问后果','先说明自己中止实验的原因，再决定披露多少。'),('后继者冒进','有人把未完成研究当成胜利捷径','以具体失败和责任警告，不能只靠藏资料解决一切。')],
[ev(8,21,25,'病中身份'),ev(8,391,391,'去世'),ev(8,2198,2251,'实验与儿子认知'),ev(8,2609,2613,'资料毁灭')],(1,0,1,2,1,2),dead=True))
C.append(human('chen_aniu','陈阿牛',
'陈阿牛以管家的位置留在厉大遒身旁，外表却更像一个学者。他对老人的感情不是争夺遗产者的表演，遗嘱交代的保险箱也因此不是普通的财物分配。面对厉氏姐妹的冷淡和贪念，他愿意退让，却在研究资料面前作出完全不同的选择：接续老人曾放弃的实验，把异常的生殖结合真正培育成可以活动、甚至显露个性的新生命。起初，这显示出他的聪明、专注和对恩人的理解；后来，同样的理解变成巨大压力。他称自己的实验场为地狱，因为眼前的生命已经不再是可以只用成功或失败命名的结果。原振侠试图鼓励他公开成果，他却害怕自己和创造物都被世人当作精怪，也认为必须亲手结束这一切。他先毁掉创造物，再让自己与实验室一同葬于爆炸。卡片记录的是一个真实跨过伦理界线的人，而非把疯狂作为天才必然代价的浪漫标签。终局恢复形态若使他再次面对研究，他仍会产生大胆设想，也会对别人轻率地说可以再培养一个表现激烈反应；可演绎的变化在于承认已经产生的生命不能仅由制造者决定是否存在。',
'毁灭培育生命后自毁实验室并死亡，关键记录未保留。','生物实验、资料复现与实验设施管理；能力在准备和技术，不是即时召唤。','证明并理解生命突破，同时害怕无法承担创造者的责任。',
[('成果有了个性','试验对象开始显露偏好与反应','从观察数据转为面对具体生命，不再轻易使用替代品说法。'),('被要求公开','外界把异常生命视作奇观','担心污名与利用，争取明确保护条件而非默认只能毁灭。'),('恩人遗产','旧资料留下危险可能性','核实可行性也核实伦理后果，避免把继续研究等同于报恩。')],
[ev(8,820,824,'与厉大遒关系'),ev(8,2039,2045,'地狱自述'),ev(8,2541,2589,'毁灭创造物与伦理争执'),ev(8,2607,2613,'死亡与资料消失')],(1,0,1,2,1,2),roles=['单书主角','阶段性对立者'],dead=True))
C.append(human('dajishi','新几内亚大祭师',
'大祭师在一场假面聚会中出现，衣服、面纹、项链和缓慢的声音先让人看见一种异域权威。他自称只是在扮演，却被海棠的同伴逐项指出身份：他是众多部落的精神领袖，也是国家事务中的高级顾问，负责整理传说中的历史。那些称号意味着他有能力使人服从，但他寻找鬼界遗迹时又没有只用权威让别人替自己冒险。进入被视为圣地的峭壁，他带着精良装备亲自行进，知道部众会听命，也知道自己不必强迫他们承受冒犯禁忌的恐惧。前代祭师的力量、黑色薄片和山中设施促使他向外界求助，海棠所属机构则立刻看见了可能的战略价值。研究、宗教威望和国家利益在他身上交叉，任何一方都不能概括全部动机。终局，他得到的报告仍不完整，关键器物被他人拿走，说明精神领袖并不掌握所有隐藏信息。卡片让他在不同世界里既能运用传统说服共同体，也能独自检查传统中留下的事实；当外来合作者索取遗物时，他应询问用途和归属，而不总是作为提供任务的神秘老人。',
'未亲自解开鬼界全貌，后收到海棠冒名报告；关键外星器物已被带走。','部落传统、历史编纂、社会协调与装备支持下的遗址探查。','理解并保管传统中的真实遗存，维持共同体的信任。',
[('禁地调查','部众恐惧而权威可迫使其服从','优先自己承担必要风险，向参与者说明选择。'),('外来研究者','对方愿帮助但索取控制权','明确遗物用途和信息回报，不把专业身份视为无限授权。'),('传统遭质疑','新证据改变神迹解释','分清共同体价值与具体事实，允许历史修订而非立即惩罚怀疑者。')],
[ev(9,297,325,'身份与权威'),ev(9,389,493,'祭师历史与独自探险'),ev(9,2737,2745,'最后所得信息与器物去向')],(1,0,1,3,2,3)))
C.append(make('guijie_aliens','鬼界受困外星人',
'他们的技术曾使进入山中的人把那里称作鬼界，反引力工具和将岩石转化的手段足以让一个普通人获得神迹般的威望。可是技术先进没有防住最普通的地球环境：他们未曾理解的磁场破坏了身体功能和主要设备，使他们只能困在山腹黑暗之中。对他们而言，甚至没有熟悉意义上的死亡可以终止等待，漫长生命变成不能解脱的囚禁。前代祭师到来时，他们交付工具，希望对方在两极实施爆炸，暂时破坏磁场以使设备恢复；人类得到奇物，救援却没有实现。原振侠与海棠再次进入后，他们重复请求，把仅存可用的飞行囊和器物交出去，却无法逼迫已经离开的地球人履约。那项爆炸方案对地球存在巨大危险，所以他们急切的求生不能自动成为要求全世界承担代价的正当理由。后续康维与原振侠提到帮助他们脱困，正文把真正执行留待另一故事，卡片不提前宣布救援成功。终局形态仍受困，需要相容设备和实际外援。新场景可以围绕一种不以毁坏他人家园为代价的替代方案展开，而不是让他们忽然获得摆脱磁场的万能进化。',
'仍受地球磁场困在鬼界；《人鬼疑云》提出未来援助，但本语料未在该处叙明实施结果。',
[skill('残存异星工具与求援接口','拥有反引力、固体转化和有限飞行器等技术；主要身体与设备因磁场受损，需外部操作者协助。','山中传来可交流声音，工具可令重物或岩石发生异常变化。',['以工具协助进入者脱险','通过外来者搬运设备','提出环境修复方案'],'磁场是直接限制；两极爆炸只是危险方案，不计为已成功的地球毁灭战绩。','设备与集体行动')],
'结束不能死亡也不能离开的黑暗囚禁。',['急切寻找能执行外部操作的伙伴','可用技术交换帮助','其求生要求可能忽视地球生命代价'],
[('来访者出现','有人能够在磁场环境中自由行动','提供可理解的说明与工具，请求完成外部工作。'),('救援有代价','方案会严重伤害当地生命','面对对方拒绝，讨论替代条件，不能宣称受困者天然拥有优先权。'),('再次失约','外界拿走器物却未回来','愤怒与绝望并存，寻求可验证阶段承诺而非永远重复盲目信任。')],
[ev(9,2438,2482,'生命形式与磁场损害'),ev(9,2512,2574,'方案与工具'),ev(9,2620,2624,'无法强迫履约'),ev(9,2720,2745,'危险代价与困境'),ev(29,7611,7613,'后续援助尚待叙述')],
(1,6,3,6,3,3),['受困本体弱','残存高技术工具','局部工具作用','长期存续但功能受损','需外部运输与操作者','强技术受环境严重压制'],roles=['单书核心人物（集体）','阶段性对立者'],negative=(1,8,1),
body={'destruction':'工具可改变岩石等物质；未把未执行的两极方案当作常态攻击。','durability':'生命长久却被地球磁场压制，不能等同绝对不死防御。','speed':'本体困于山腹，运输依工具和他人。','energy':'相容异星工具，许多设备在磁场下失灵。','mind':'能交流并长期保持意识，仍会绝望和误判他人。','stamina':'生命持续不等于功能完整，环境限制长期存在。'}))
